text:
{
  "table": "timesheets",
  "columns": [
    {
      "target": "employee_id",
      "source": [
        "id"
      ],
      "transform": "text",
      "params": {
        "case": "upper"
      },
      "confidence": 1.0,
      "note": "Maps employee id directly"
    },
    {
      "target": "employee_name",
      "source": [
        "name.first",
        "name.last"
      ],
      "transform": "concat",
      "params": {},
      "confidence": 1.0,
      "note": "Combines first and last name with a space"
    },
    {
      "target": "work_date",
      "source": [
        "entries.date"
      ],
      "transform": "date",
      "params": {
        "format": "%Y-%m-%d"
      },
      "confidence": 1.0,
      "note": "Maps entry date"
    },
    {
      "target": "project_code",
      "source": [
        "entries.project"
      ],
      "transform": "text",
      "params": {
        "case": "upper"
      },
      "confidence": 1.0,
      "note": "Maps project code"
    },
    {
      "target": "hours_normal",
      "source": [
        "entries.normal"
      ],
      "transform": "number",
      "params": {
        "decimal": "."
      },
      "confidence": 1.0,
      "note": "Maps normal hours"
    },
    {
      "target": "hours_overtime",
      "source": [
        "entries.overtime"
      ],
      "transform": "number",
      "params": {
        "decimal": "."
      },
      "confidence": 1.0,
      "note": "Maps overtime hours"
    }
  ],
  "ignore": {
    "entries.#": "Array index or row count within the entry list, redundant with grain."
  },
  "review": [
    "Check if @period (2026-W09) needs to be recorded or validated against the work dates."
  ]
}
